#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES. One stage per thing the human does, in dependency order.
# ──────────────────────────────────────────────────────────────────────────

CONFIG_DIR="$HOME/.config/gws"
STAMP=$(date +%Y%m%dT%H%M%S)
BACKUP_DIR="$CONFIG_DIR/backup-$STAMP"
PROJECT_NAME="bb-inbox-personal"

# installed_client FILE prints the project id of an OAuth client json, or nothing.
installed_client() {
  node -e '
    const fs = require("node:fs");
    try {
      const raw = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
      const client = raw.installed || raw.web || {};
      process.stdout.write(JSON.stringify({ kind: raw.installed ? "installed" : raw.web ? "web" : "unknown", project: String(client.project_id || "") }));
    } catch { process.stdout.write("{\"kind\":\"unreadable\",\"project\":\"\"}"); }
  ' "$1" 2>/dev/null || printf '{"kind":"unreadable","project":""}'
}

run_wizard() {

TOTAL_STAGES=6

banner "Move the personal Gmail client to its own Cloud project"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Back up the client this account uses now"
say "The personal Gmail grant was issued by a Cloud project that also serves"
say "other work (the console calls it 'executor-mcp-gateway'). Moving it means a"
say "new project, a new OAuth client, and a fresh consent — which you need anyway."
say ""
say "Nothing is deleted. These files move into a timestamped backup first:"
note "$CONFIG_DIR/client_secret.json     the client that issues the grant"
note "$CONFIG_DIR/credentials.enc         the encrypted refresh token for it"
note "$CONFIG_DIR/token_cache.json        its cached access token"
say ""
[[ -f "$CONFIG_DIR/client_secret.json" ]] || { warn "No $CONFIG_DIR/client_secret.json: this is not the account to move."; return; }
current=$(installed_client "$CONFIG_DIR/client_secret.json")
say "Current client: $current"
confirm "Back these up to $BACKUP_DIR now?" || { warn "Nothing was changed."; return; }
mkdir -p "$BACKUP_DIR"; chmod 700 "$BACKUP_DIR"
for file in client_secret.json credentials.enc token_cache.json; do
  [[ -f "$CONFIG_DIR/$file" ]] && { cp -p "$CONFIG_DIR/$file" "$BACKUP_DIR/$file" && printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$file"; }
done
SKIPPED+=("delete $BACKUP_DIR once a face has appeared in the inbox")
note "The old credentials stay in place for now: the new client overwrites them in stage 5."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the project"
open_url "https://console.cloud.google.com/projectcreate"
step "Name it $PROJECT_NAME."
step "Leave the location as No organization, then press Create."
step "When it lands, copy the project ID from the project picker — not the name."
say ""
note "A generated id such as bb-inbox-personal-481203 is normal: ids are unique and"
note "cannot be chosen freely. Ids are also permanent, so an id never needs renaming."
while true; do
  ask GCP_PROJECT_ID "Paste the new project ID:"
  if [[ "$GCP_PROJECT_ID" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]]; then break; fi
  warn "That does not look like a project id (lowercase letters, digits, hyphens)."
done
say ""
say "Using project: $GCP_PROJECT_ID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Set up its consent screen"
open_url "https://console.cloud.google.com/auth/overview?project=$GCP_PROJECT_ID"
step "Press Get started."
step "App name: Unified Inbox. Support email: your own address."
step "Audience: External. Then finish and press Create."
step "Open the Audience tab and add your Gmail address under Test users."
say ""
note "External + Testing is deliberate: no verification review is needed, and the"
note "only people who can consent are the test users you list."
note "Route if the link has moved: APIs & Services → OAuth consent screen."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the OAuth client and download it"
open_url "https://console.cloud.google.com/apis/credentials?project=$GCP_PROJECT_ID"
step "Press Create credentials → OAuth client ID."
step "Application type: Desktop app. Name it Unified Inbox desktop."
step "Press Create, then Download JSON on the row that appears."
say ""
note "A Desktop client is the kind this OAuth flow needs; a Web client has no"
note "redirect that works from a terminal, and the login fails with a mismatch."
pause "Press Enter once the JSON is in your Downloads folder."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Install it as the client this account logs in with"
downloaded="$HOME/Downloads/client_secret.json"
while true; do
  ask CLIENT_JSON "Path to the downloaded JSON:" 
  [[ -z "$CLIENT_JSON" ]] && CLIENT_JSON="$downloaded"
  [[ -f "$CLIENT_JSON" ]] || { warn "No file at $CLIENT_JSON"; continue; }
  info=$(installed_client "$CLIENT_JSON")
  kind=$(printf '%s' "$info" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{process.stdout.write(JSON.parse(s).kind)}catch{process.stdout.write("unreadable")}})')
  project=$(printf '%s' "$info" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{process.stdout.write(JSON.parse(s).project)}catch{process.stdout.write("")}})')
  if [[ "$kind" != "installed" ]]; then warn "That is a '$kind' client; a Desktop client is required."; continue; fi
  if [[ "$project" != "$GCP_PROJECT_ID" ]]; then
    warn "That client belongs to project '${project:-unknown}', not $GCP_PROJECT_ID."
    confirm "Install it anyway?" || continue
  fi
  break
done
confirm "Replace $CONFIG_DIR/client_secret.json with this client?" || { warn "Nothing was changed."; return; }
install -m 600 "$CLIENT_JSON" "$CONFIG_DIR/client_secret.json"
# The old refresh token belongs to the old client, so it is removed rather than left to be
# tried and refused: the re-consent in the next step issues a new one.
for file in credentials.enc token_cache.json; do
  [[ -f "$CONFIG_DIR/$file" ]] && rm -f "$CONFIG_DIR/$file" && printf '  %s✓%s cleared %s\n' "$GREEN" "$RESET" "$file"
done
printf '  %s✓ installed%s %s\n' "$GREEN" "$RESET" "$CONFIG_DIR/client_secret.json (0600)"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "What is true now"
final=$(installed_client "$CONFIG_DIR/client_secret.json")
say "The personal client: $final"
say ""
say "Next: run the personal consent wizard, which reads this project's id from"
say "that file and walks the People API and the two contact scopes on it."
say ""
note "./_tools/gmail-faces-personal.sh"
say ""
note "Until that finishes, personal Gmail has no grant: the inbox shows it as a"
note "source that cannot be read, which is expected, not a new fault."

finish
}

run_wizard "$@"; exit
